// The fixtures under testdata are Python's behavior, generated by
// testdata/gen_fixtures.py (never edited by hand).

var fakepiBin string

func TestMain(m *testing.M) {
	dir, err := os.MkdirTemp("", "capture-fakepi-")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	goBin, err := exec.LookPath("go")
	if err != nil {
		goBin = filepath.Join(runtime.GOROOT(), "bin", "go")
	}
	fakepiBin = filepath.Join(dir, "pi")
	cmd := exec.Command(goBin, "build", "-o", fakepiBin, "./internal/testutil/fakepi")
	cmd.Dir = "../.."
	if out, err := cmd.CombinedOutput(); err != nil {
		fmt.Fprintf(os.Stderr, "build fakepi: %v\n%s", err, out)
		os.RemoveAll(dir)
		os.Exit(1)
	}
	code := m.Run()
	os.RemoveAll(dir)
	os.Exit(code)
}

func plain(t *testing.T, v any) any {
	t.Helper()
	raw, err := jsonx.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	var out any
	if err := json.Unmarshal(raw, &out); err != nil {
		t.Fatal(err)
	}
	return out
}

func decodeObj(t *testing.T, raw []byte) *jsonx.Object {
	t.Helper()
	v, err := jsonx.Decode(raw)
	if err != nil {
		t.Fatal(err)
	}
	o, _ := v.(*jsonx.Object)
	return o
}

// isolatedHome points HOME at a fresh realpath'd dir with no XDG state.
func isolatedHome(t *testing.T) string {
	t.Helper()
	home, err := filepath.EvalSymlinks(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	t.Setenv("HOME", home)
	t.Setenv("XDG_STATE_HOME", "")
	t.Setenv("PI_CODING_AGENT_DIR", "")
	return home
}

func defaultsCfg() *config.Resolved {
	return &config.Resolved{Values: config.Defaults()}
}

type captureCase struct {
	Name     string          `json:"name"`
	Prompt   string          `json:"prompt"`
	Resume   *string         `json:"resume"`
	Class    string          `json:"class"`
	Watchdog json.RawMessage `json:"watchdog"`
	Want     json.RawMessage `json:"want"`
}

// End to end: Go's capture over fakepi == Python's _capture_with_grants
// over the same fakepi, sandbox off.
func TestCaptureMatchesPython(t *testing.T) {
	raw, err := os.ReadFile("testdata/capture_fixtures.json")
	if err != nil {
		t.Fatal(err)
	}
	var fx struct{ Cases []captureCase }
	if err := json.Unmarshal(raw, &fx); err != nil {
		t.Fatal(err)
	}
	if len(fx.Cases) == 0 {
		t.Fatal("no fixtures")
	}
	isolatedHome(t)
	t.Setenv("PATH", filepath.Dir(fakepiBin)+string(os.PathListSeparator)+os.Getenv("PATH"))
	work := t.TempDir()
	for _, c := range fx.Cases {
		t.Run(c.Name, func(t *testing.T) {
			t.Parallel()
			cfg := defaultsCfg()
			cfg.Values.Object("sandbox").Set("mode", "off")
			if string(c.Watchdog) != "null" && len(c.Watchdog) > 0 {
				cfg.Values.Set("watchdog", decodeObj(t, c.Watchdog))
			}
			spec := sandbox.Prepare("pi", work, cfg, "m", "")
			resume := ""
			if c.Resume != nil {
				resume = *c.Resume
			}
			got, _, err := RunWithGrants(context.Background(), Request{
				Executor: "pi", Model: "m", Effort: "low", Workdir: work, Prompt: c.Prompt,
				Resume: resume, Class: c.Class, SandboxTree: work, Sandbox: spec, Cfg: cfg,
			})
			if err != nil {
				t.Fatal(err)
			}
			g := plain(t, got).(map[string]any)
			if rw, ok := g["runaway"].(map[string]any); ok {
				for _, k := range []string{"elapsed_s", "runtime_s"} {
					if v, ok := rw[k].(float64); !ok || v < 0 {
						t.Errorf("runaway %s = %v", k, rw[k])
					}
					rw[k] = "<S>"
				}
			}
			var want any
			if err := json.Unmarshal(c.Want, &want); err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(any(g), want) {
				t.Errorf("got  %v\nwant %v", g, want)
			}
			if k, w := got.Keys(), decodeObj(t, c.Want).Keys(); !slices.Equal(k, w) {
				t.Errorf("keys %v, want %v", k, w)
			}
		})
	}
}

type cannedRun struct {
	Stdout   string `json:"stdout"`
	Stderr   string `json:"stderr"`
	ExitCode int    `json:"exit_code"`
}

type grantCase struct {
	Name    string          `json:"name"`
	Backend string          `json:"backend"`
	Runs    []cannedRun     `json:"runs"`
	Calls   json.RawMessage `json:"calls"`
	Want    json.RawMessage `json:"want"`
	Learned []string        `json:"learned"`
	Dirs    []string        `json:"dirs"`
}

// The grant + resume loop over canned pi transcripts == Python's.
func TestGrantLoopMatchesPython(t *testing.T) {
	raw, err := os.ReadFile("testdata/grants_fixtures.json")
	if err != nil {
		t.Fatal(err)
	}
	var fx struct{ Cases []grantCase }
	if err := json.Unmarshal(raw, &fx); err != nil {
		t.Fatal(err)
	}
	if len(fx.Cases) == 0 {
		t.Fatal("no fixtures")
	}
	for _, c := range fx.Cases {
		t.Run(c.Name, func(t *testing.T) {
			home := isolatedHome(t)
			tree := filepath.Join(home, "work", "tree")
			for _, d := range []string{"work/tree", ".pnpm-store", ".config", ".ssh", ".cache", ".pub-cache", ".npm", ".cargo"} {
				if err := os.MkdirAll(filepath.Join(home, d), 0o755); err != nil {
					t.Fatal(err)
				}
			}
			if err := os.WriteFile(filepath.Join(home, ".pnpm-store", "probe.txt"), []byte("x"), 0o644); err != nil {
				t.Fatal(err)
			}
			spec := sandbox.Spec{Backend: c.Backend, Enforced: true, Limits: []string{},
				Writable: []string{tree}, Policy: &sandbox.Policy{Writable: []string{tree},
					DenyRead: []string{filepath.Join(home, ".ssh")}}}
			queue := append([]cannedRun(nil), c.Runs...)
			var calls []any
			restore := swapSeams(
				func(_ context.Context, _ Request, _ sandbox.Spec, prompt, resume string) (*jsonx.Object, *denialInput, error) {
					var r any
					if resume != "" {
						r = resume
					}
					calls = append(calls, map[string]any{"prompt": prompt, "resume": r})
					if len(queue) == 0 {
						t.Fatal("more runs than canned")
					}
					run := queue[0]
					queue = queue[1:]
					stdout := strings.ReplaceAll(run.Stdout, "<HOME>", home)
					stderr := strings.ReplaceAll(run.Stderr, "<HOME>", home)
					return pi.ParseJSONL(stdout, stderr, run.ExitCode, resume != ""),
						&denialInput{Stdout: stdout, Stderr: stderr}, nil
				},
				func(string, string, *config.Resolved, string, string) sandbox.Spec { return spec },
			)
			defer restore()
			got, _, err := RunWithGrants(context.Background(), Request{
				Executor: "pi", Model: "m", Effort: "low", Workdir: tree, Prompt: "task",
				SandboxTree: tree, Sandbox: spec, Cfg: defaultsCfg(),
			})
			if err != nil {
				t.Fatal(err)
			}
			norm := func(v any) any {
				raw, _ := jsonx.Marshal(v)
				var out any
				_ = json.Unmarshal([]byte(strings.ReplaceAll(string(raw), home, "<HOME>")), &out)
				return out
			}
			var want, wantCalls any
			_ = json.Unmarshal(c.Want, &want)
			_ = json.Unmarshal(c.Calls, &wantCalls)
			if g := norm(got); !reflect.DeepEqual(g, want) {
				t.Errorf("result\n got  %v\n want %v", g, want)
			}
			if g := norm(calls); !reflect.DeepEqual(g, wantCalls) {
				t.Errorf("calls\n got  %v\n want %v", g, wantCalls)
			}
			learned, _ := sandbox.LoadLearned()
			gotLearned := []string{}
			for _, g := range learned.Grants {
				gotLearned = append(gotLearned, strings.ReplaceAll(g.Path, home, "<HOME>"))
			}
			if !slices.Equal(gotLearned, c.Learned) {
				t.Errorf("learned %v, want %v", gotLearned, c.Learned)
			}
			if d := dirsUnder(t, home); !slices.Equal(d, c.Dirs) {
				t.Errorf("dirs %v, want %v", d, c.Dirs)
			}
		})
	}
}

func swapSeams(run func(context.Context, Request, sandbox.Spec, string, string) (*jsonx.Object, *denialInput, error),
	prep func(string, string, *config.Resolved, string, string) sandbox.Spec) func() {
	oldRun, oldPrep := runner, prepareSpec
	runner, prepareSpec = run, prep
	return func() { runner, prepareSpec = oldRun, oldPrep }
}

func dirsUnder(t *testing.T, root string) []string {
	t.Helper()
	var out []string
	err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() && p != root {
			rel, _ := filepath.Rel(root, p)
			out = append(out, rel)
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	slices.Sort(out)
	return out
}
